    'global.emails.guest_guest_payment_donation.subject' => 'Has hecho una donación a \'{{DONATION_TITLE}}\': {{WEBSITE_TITLE}}',
    'global.emails.guest_guest_payment_donation.body' => 'Hola, <strong>{{NAME}}</strong>,<br /><br />Este es el aviso oficial por correo electrónico para informarte que tu donación se ha realizado correctamente. Gracias por tu contribución.<br /><br />Saludos,<br />El equipo de {{WEBSITE_TITLE}}.',
