    'global.emails.user_guest_payment_product.body' => 'Hola, <strong>{{NAME}}</strong>,<br /><br />Acabas de recibir un nuevo pago de uno de tus visitantes por uno de tus productos.<br /><br /><strong>Correo electrónico:</strong> {{EMAIL}}<br /><strong>Nombre:</strong> {{PAYER_NAME}}<br /><strong>Importe total:</strong> {{TOTAL_AMOUNT}}<br /><strong>Moneda:</strong> {{CURRENCY}}<br /><strong>Procesador:</strong> {{PROCESSOR}}<br /><strong>Producto:</strong> {{PRODUCT_TITLE}}<br /><br /><a href="{{GUEST_PAYMENT_LINK}}" class="cta">Ver pago</a><br /><br />Saludos,<br />El equipo de {{WEBSITE_TITLE}}.',
    'global.emails.guest_guest_payment_product.subject' => 'Compraste \'{{PRODUCT_TITLE}}\': {{WEBSITE_TITLE}}',
    'global.emails.guest_guest_payment_product.body' => 'Hola, <strong>{{NAME}}</strong>,<br /><br />Este es el aviso oficial por correo electrónico para confirmar que tu pedido se realizó correctamente. Puedes usar el enlace de descarga que aparece a continuación para descargar el producto que compraste.<br /><br /><strong>Enlace de descarga:</strong> {{DOWNLOAD_LINK}}<br /><br />Saludos,<br />El equipo de {{WEBSITE_TITLE}}.',
