    'global.emails.user_guest_payment_service.body' => 'Hola, <strong>{{NAME}}</strong>,<br /><br />Acabas de recibir un nuevo pago de uno de tus visitantes por uno de tus servicios.<br /><br /><strong>Correo electrónico:</strong> {{EMAIL}}<br /><strong>Nombre:</strong> {{PAYER_NAME}}<br /><strong>Importe total:</strong> {{TOTAL_AMOUNT}}<br /><strong>Moneda:</strong> {{CURRENCY}}<br /><strong>Procesador:</strong> {{PROCESSOR}}<br /><strong>Servicio:</strong> {{SERVICE_TITLE}}<br /><strong>Mensaje:</strong> {{MESSAGE}}<br /><br /><a href="{{GUEST_PAYMENT_LINK}}" class="cta">Ver pago</a><br /><br />Saludos,<br />El equipo de {{WEBSITE_TITLE}}.',
    'global.emails.guest_guest_payment_service.subject' => 'Pagaste por \'{{SERVICE_TITLE}}\': {{WEBSITE_TITLE}}',
    'global.emails.guest_guest_payment_service.body' => 'Hola, <strong>{{NAME}}</strong>,<br /><br />Este es el aviso oficial por correo electrónico para informarte de que tu pedido se ha realizado correctamente. El proveedor del servicio se pondrá en contacto contigo lo antes posible.<br /><br />Saludos,<br />El equipo de {{WEBSITE_TITLE}}.',
