    'global.emails.user_plan_expiry_reminder.body' => 'Hola, <strong>{{NAME}}</strong>,<br /><br />Este es un sencillo recordatorio de que tu <strong>plan {{PLAN_NAME}}</strong> vencerá en <strong>{{DAYS_UNTIL_EXPIRATION}} días</strong>.<br /><br />Debes renovar tu plan si quieres seguir usando nuestro sitio web con todas sus funciones.<br /><br /><a href="{{USER_PLAN_RENEW_LINK}}" class="cta">Renovar el plan</a><br /><br />Saludos,<br />El equipo de {{WEBSITE_TITLE}}.',
    'global.emails.user_plan_expired.subject' => 'Tu plan ha caducado: {{WEBSITE_TITLE}}',
    'global.emails.user_plan_expired.body' => 'Hola, <strong>{{NAME}}</strong>,<br /><br />Tu <strong>plan {{PLAN_NAME}}</strong> ha caducado porque no has renovado tu membresía.<br /><br />Si deseas seguir usando nuestro sitio web con todas las funciones que tenías, tendrás que renovar tu membresía.<br /><br /><a href="{{USER_PLAN_RENEW_LINK}}" class="cta">Renovar plan</a><br /><br />Saludos,<br />El equipo de {{WEBSITE_TITLE}}.',
    'global.emails.user_deletion_reminder.subject' => 'Tu cuenta se eliminará en {{DAYS_UNTIL_DELETION}} días: {{WEBSITE_TITLE}}',
    'global.emails.user_deletion_reminder.body' => 'Hola, <strong>{{NAME}}</strong>,<br /><br />Te enviamos este breve correo para recordarte que tu cuenta se eliminará dentro de {{DAYS_UNTIL_DELETION}} días porque ha estado inactiva.<br /><br />Si quieres cancelar la eliminación, solo tienes que iniciar sesión en tu cuenta y se detendrá el proceso de eliminación.<br /><br /><a href="{{LOGIN_LINK}}">Inicia sesión y detén la eliminación</a><br /><br />Saludos,<br />El equipo de {{WEBSITE_TITLE}}.',
    'global.emails.auto_delete_inactive_users.subject' => 'Tu cuenta se ha eliminado: {{WEBSITE_TITLE}}',
    'global.emails.auto_delete_inactive_users.body' => 'Hola, <strong>{{NAME}}</strong>,<br /><br />Te enviamos este sencillo correo electrónico para informarte de que tu cuenta se ha eliminado por haber estado inactiva durante más de {{INACTIVITY_DAYS}} días.<br /><br />Si quieres recuperar el acceso, tendrás que crear otra cuenta con nosotros.<br /><br /><a href="{{REGISTER_LINK}}" class="cta">Volver a registrarte</a><br /><br />Saludos,<br />El equipo de {{WEBSITE_TITLE}}.',
