    'dashboard.onboarding_intro.eyebrow' => 'Guía de FCC',
    'dashboard.onboarding_intro.title' => 'Empieza de forma sencilla y descubre en un solo lugar lo que ya tienes',
    'dashboard.onboarding_intro.text' => 'FCC te ofrece una aplicación personal, contenido para el blog, herramientas de embudo, asistencia y recomendaciones de IA para que puedas generar más interés en los productos Forever, los registros y los contactos.',
    'dashboard.onboarding_intro.item_1_title' => 'Aplicaciones FCC y enlaces para compartir',
    'dashboard.onboarding_intro.item_1_text' => 'Edita tu aplicación y comparte enlaces que lleven a tu recomendación.',
    'dashboard.onboarding_intro.item_2_title' => 'Clics, registros y contactos',
    'dashboard.onboarding_intro.item_2_text' => 'Descubre de inmediato qué genera interés, dónde se producen los registros y los contactos, y qué vale la pena repetir.',
    'dashboard.onboarding_intro.item_3_title' => 'IA y soporte',
    'dashboard.onboarding_intro.item_3_text' => 'La IA ayuda con las próximas acciones, mientras que el soporte te permite hacer preguntas y sugerir temas para los seminarios web.',
    'dashboard.onboarding_intro.primary' => 'Iniciar tutorial',
    'dashboard.onboarding_intro.secondary' => 'Cómo funciona FCC',
    'dashboard.onboarding_modal.title' => 'Cómo funciona FCC',
    'dashboard.onboarding_modal.subtitle' => 'En 6 pasos breves, descubre qué tienes, qué te aporta y qué hacer primero.',
    'dashboard.onboarding_modal.step_1_title' => '1. El panel como punto de partida',
    'dashboard.onboarding_modal.step_1_text' => 'El panel es el espacio principal para comprender el sistema FCC: aquí puedes ver tu señal de actividad, las guías educativas, las siguientes acciones y un resumen de lo que ya está dando resultados.',
    'dashboard.onboarding_modal.step_2_title' => '2. Menús principales y contenido',
    'dashboard.onboarding_modal.step_2_text' => 'Desde el menú principal puedes acceder al contenido de Forever Card Club, los productos Forever, el blog, la sección de contacto y el panel. Este es el recorrido que sigues para aprender, compartir contenido y desarrollar tu negocio Forever.',
    'dashboard.onboarding_modal.step_3_title' => '3. Aplicaciones y enlaces de FCC',
    'dashboard.onboarding_modal.step_3_text' => 'Tus aplicaciones de FCC funcionan como tu base digital personal, desde la que guías a los visitantes hacia productos, registros, contactos y otras acciones clave.',
    'dashboard.onboarding_modal.step_4_title' => '4. Blog y recomendaciones',
    'dashboard.onboarding_modal.step_4_text' => 'El blog y la sección Forever Products se utilizan para compartir contenido educativo y sobre productos con tu recomendación, de modo que el interés por los productos y la tienda web siga vinculado a ti.',
    'dashboard.onboarding_modal.step_5_title' => '5. Señal, IA y tu plan de crecimiento',
    'dashboard.onboarding_modal.step_5_text' => 'FCC registra qué acciones conducen realmente a la tienda web de Forever, y la IA utiliza esa señal para sugerir próximos pasos más claros y un mejor plan de crecimiento.',
    'dashboard.onboarding_modal.step_6_title' => '6. Temas de apoyo, formación y seminarios web',
    'dashboard.onboarding_modal.step_6_text' => 'Cuando te quedes sin ideas o quieras probar una nueva dirección, el apoyo y los temas de los seminarios web te ofrecerán explicaciones adicionales, ayuda y un espacio para sugerir qué es lo más importante para tu próxima etapa de crecimiento.',
    'dashboard.onboarding_modal.primary' => 'Iniciar tutorial',
    'dashboard.onboarding_modal.secondary' => 'Solo quiero que me muestres cómo funciona',
    'dashboard.tutorials.eyebrow' => 'Guías rápidas',
    'dashboard.tutorials.title' => 'Tutoriales para tus primeras recomendaciones',
    'dashboard.tutorials.text' => 'Abre guías breves para acciones específicas que te ayudan a aumentar el interés, los clics y las recomendaciones mediante el sistema FCC.',
    'dashboard.tutorials.blog_referral.badge' => 'Blog de FCC + recomendación',
    'dashboard.tutorials.blog_referral.title' => 'Comparte un artículo con tu propio enlace de recomendación',
    'dashboard.tutorials.blog_referral.text' => 'Esta guía te lleva desde la sección Forever Products hasta un enlace listo para usar que conecta automáticamente tu contenido, recomendación y visita a la tienda en línea.',
    'dashboard.tutorials.blog_referral.button' => 'Guía de inicio',
    'dashboard.tutorials.blog_referral.modal_title' => 'Cómo compartir un artículo con tu propio enlace de recomendación',
    'dashboard.tutorials.blog_referral.modal_subtitle' => 'Desde abrir la sección de productos Forever hasta copiar un enlace listo para usar que ya incluye tu recomendación.',
    'dashboard.tutorials.blog_referral.modal_callout' => 'Cuando compartes un artículo de esta manera, FCC añade automáticamente tu recomendación al enlace que envías. Es la forma más sencilla de hacer que el contenido del producto refleje de inmediato tu señal y recomendación.',
    'dashboard.tutorials.blog_referral.modal_primary' => 'Iniciar guía paso a paso',
    'dashboard.tutorials.blog_referral.next_open_article' => 'Abrir artículo',
    'dashboard.tutorials.blog_referral.step_1_title' => '1. Haz clic en Forever Products',
    'dashboard.tutorials.blog_referral.step_1_text' => 'Abre la sección Forever Products en el menú de la izquierda. Esto te lleva al blog con contenido de productos listo para compartir.',
    'dashboard.tutorials.blog_referral.step_2_title' => '2. Elige un producto o búscalo',
    'dashboard.tutorials.blog_referral.step_2_text' => 'Dentro del blog, elige el producto que quieres recomendar. Si quieres encontrar más rápido el artículo adecuado, usa la búsqueda y abre el producto que corresponda al interés de la persona.',
    'dashboard.tutorials.blog_referral.step_3_title' => '3. Usa el área para compartir con la recomendación',
    'dashboard.tutorials.blog_referral.step_3_text' => 'En la parte superior del artículo verás la sección «Comparte esta página con tu recomendación». Allí puedes copiar el enlace o compartirlo directamente mediante los botones disponibles.',
    'dashboard.tutorials.blog_referral.step_4_title' => '4. El enlace ya incluye tu recomendación',
    'dashboard.tutorials.blog_referral.step_4_text' => 'El enlace que copias o compartes ya contiene tu enlace de recomendación único. Si un visitante abre la tienda en línea de Forever a través de este enlace, esa visita y la recomendación quedan vinculadas a tu cuenta.',
    'dashboard.tutorials.blog_referral.step_5_title' => 'Por qué es importante',
    'dashboard.tutorials.blog_referral.step_5_text' => 'Estos clics refuerzan tu señal de ventas, ayudan a posicionar tu aplicación Forever Card y crean un rastro claro de interés en Forever Living Products.',
    'dashboard.tutorials.blog_referral.category_step_1_title' => 'Ahora estás en Productos Forever',
    'dashboard.tutorials.blog_referral.category_step_1_text' => 'Esta es la sección del blog de productos, con contenido que puedes compartir mediante tu recomendación. Ahora la guía te lleva al artículo adecuado y al enlace de recomendación para compartir.',
    'dashboard.tutorials.blog_referral.category_step_2_title' => 'Encuentra el producto que quieres recomendar',
    'dashboard.tutorials.blog_referral.category_step_2_text' => 'Si ya sabes qué producto quieres enviar, escríbelo en la búsqueda. Es la forma más rápida de encontrar el artículo que corresponde al interés de la persona.',
    'dashboard.tutorials.blog_referral.category_step_3_title' => 'Abrir el artículo sobre el producto',
    'dashboard.tutorials.blog_referral.category_step_3_text' => 'Para esta guía, abriremos el primer artículo visible. Dentro del artículo, la guía continuará y te mostrará dónde copiar o compartir tu enlace de recomendación.',
    'dashboard.tutorials.blog_referral.article_step_1_title' => 'Aquí se genera el enlace de recomendación',
    'dashboard.tutorials.blog_referral.article_step_1_text' => 'En la parte superior del artículo puedes ver la fila para compartir con tu recomendación. Cuando compartes desde esta sección, FCC añade tu recomendación personal al enlace.',
    'dashboard.tutorials.blog_referral.article_step_2_title' => 'Comprueba cómo funciona el sistema',
    'dashboard.tutorials.blog_referral.article_step_2_text' => 'Al hacer clic en Cómo funciona, se abre una breve explicación que indica que tu recomendación se añade automáticamente y que la visita permanece vinculada a tu cuenta.',
    'dashboard.tutorials.blog_referral.article_step_3_title' => 'Comparte el artículo con los botones prediseñados',
    'dashboard.tutorials.blog_referral.article_step_3_text' => 'Aquí puedes compartir al instante el artículo en las redes sociales o enviarlo en un mensaje. Todas las opciones usan el mismo enlace con tu recomendación.',
    'dashboard.tutorials.blog_referral.article_step_4_title' => 'Copia tu enlace terminado',
    'dashboard.tutorials.blog_referral.article_step_4_text' => 'Si quieres pegar el enlace manualmente en un mensaje, una historia o una publicación, cópialo aquí. Si un visitante accede a la tienda web de Forever mediante ese enlace, seguirá conectado a tu recomendación.',
    'dashboard.tour.launch' => 'Iniciar tutorial',
    'dashboard.tour.replay' => 'Reproducir el tutorial',
    'dashboard.tour.next' => 'Siguiente',
    'dashboard.tour.prev' => 'Atrás',
    'dashboard.tour.skip' => 'Omitir',
    'dashboard.tour.finish' => 'Finalizar',
    'dashboard.tour.step_guide_title' => 'Guía de esta página',
    'dashboard.tour.step_guide_text' => 'En todas las páginas importantes de FCC, la guía está en la esquina superior derecha. Haz clic en ese botón cuando quieras ver instrucciones breves, paso a paso, para la página que estás consultando.',
    'dashboard.tour.step_sidebar_title' => 'Menú y áreas de trabajo de FCC',
    'dashboard.tour.step_sidebar_text' => 'Este es el menú principal de FCC dentro de tu sistema de usuario. Desde aquí puedes abrir el panel, las aplicaciones, tu plan de crecimiento, los resultados, la formación y el contenido de productos que respaldan tu negocio diario de Forever.',
    'dashboard.tour.step_menu_apps_title' => 'aplicaciones de FCC',
    'dashboard.tour.step_menu_apps_text' => 'Aquí abres las aplicaciones de tu Forever Card. Son tu base digital personal para dirigir a los visitantes hacia productos, registros, contactos y otras acciones importantes.',
    'dashboard.tour.step_menu_ai_plan_title' => 'Plan de crecimiento con IA',
    'dashboard.tour.step_menu_ai_plan_text' => 'Aquí puedes abrir y seguir tu plan de crecimiento. La IA usa las señales de tus aplicaciones, el contenido de tu blog y los clics en tu tienda en línea para sugerirte los mejores próximos pasos para los próximos días.',
    'dashboard.tour.step_menu_results_title' => 'Resultados de FCC',
    'dashboard.tour.step_menu_results_text' => 'Aquí puedes ver si tu sistema realmente está dando resultados. Esta sección te ayuda a hacer un seguimiento de los clics, el progreso y las señales que muestran qué vale la pena reforzar.',
    'dashboard.tour.step_menu_education_title' => 'Formación Forever',
    'dashboard.tour.step_menu_education_text' => 'Esta sección contiene formación en video y explicaciones que te ayudan a entender el sistema, seguir los pasos y aplicar lo que aprendes en tu trabajo cotidiano.',
    'dashboard.tour.step_menu_products_title' => 'Productos Forever',
    'dashboard.tour.step_menu_products_text' => 'Aquí se abren los artículos sobre productos y el contenido de recomendaciones. Es uno de los principales lugares desde los que compartes contenido con tus recomendaciones y despiertas el interés de posibles clientes para dirigirlos a la tienda online de Forever.',
    'dashboard.tour.step_navbar_title' => 'Menú principal de FCC',
    'dashboard.tour.step_navbar_text' => 'El menú superior es la navegación principal para acceder a la formación, los productos, el contenido del blog, los contactos y volver al panel. Aquí comienza la comprensión de todo el sistema FCC.',
    'dashboard.tour.step_menu_forever_club_title' => 'Forever Card Club',
    'dashboard.tour.step_menu_forever_club_text' => 'Aquí se abre la información principal de FCC, las explicaciones del sistema y el contenido que te ayuda a entender cómo trabajan en conjunto las aplicaciones, las recomendaciones y las herramientas para crear un negocio de Forever.',
    'dashboard.tour.step_menu_forever_products_title' => 'Productos Forever',
    'dashboard.tour.step_menu_forever_products_text' => 'Aquí encontrarás contenido sobre productos y artículos que puedes compartir con tu recomendación. Es una parte importante para despertar interés y guiar a los visitantes hacia la tienda en línea de Forever.',
    'dashboard.tour.step_menu_blog_title' => 'Blog',
    'dashboard.tour.step_menu_blog_text' => 'El blog te ofrece contenido educativo y empresarial más amplio que puedes usar en publicaciones y mensajes, y para generar confianza mediante contenido útil, no solo mediante la venta directa.',
    'dashboard.tour.step_menu_contact_title' => 'Contacto',
    'dashboard.tour.step_menu_contact_text' => 'Aquí puedes encontrar contactos y soporte para preguntas adicionales. Si algo no está claro o necesitas orientación, este es uno de los lugares donde puedes pedir ayuda.',
    'dashboard.tour.step_menu_dashboard_title' => 'Ir al panel',
    'dashboard.tour.step_menu_dashboard_text' => 'El panel es tu centro de control. Aquí haces seguimiento de tus señales, aprendes con guías, ves qué funciona y decides cuál debería ser tu siguiente paso.',
    'dashboard.tour.step_hero_title' => 'Página de inicio de tu trabajo con FCC',
    'dashboard.tour.step_hero_text' => 'Esta sección superior resume dónde estás ahora, cuál es tu enfoque y cuáles son tus vías más rápidas para acceder a las aplicaciones, la asistencia y las guías educativas.',
    'dashboard.tour.step_growth_title' => 'Señales y desbloqueos',
    'dashboard.tour.step_growth_text' => 'Aquí puedes ver cuánta actividad real dirige a la tienda web de Forever Living a través de tu aplicación FCC, blog y otras herramientas. Esa señal determina el ritmo de la ayuda de IA y los próximos desbloqueos de tu plan de crecimiento.',
    'dashboard.tour.step_tutorials_title' => 'Mini tutoriales y formación',
    'dashboard.tour.step_tutorials_text' => 'Aquí puedes abrir guías prácticas breves para acciones específicas. Así funciona la formación de FCC en la práctica: no solo mediante teoría, sino también con pequeños pasos que puedes aplicar de inmediato.',
    'dashboard.tour.step_workbench_title' => 'Espacio de trabajo',
    'dashboard.tour.step_workbench_text' => 'Aquí puedes ver de inmediato qué funciona, dónde se pierden resultados y qué partes del sistema ya despiertan interés. Esto te ayuda a tomar decisiones basadas en señales reales, no en conjeturas.',
    'dashboard.tour.step_chart_title' => 'Clics que generan resultados',
    'dashboard.tour.step_chart_text' => 'El gráfico separa app → Forever, blog → Forever, registros y contactos del embudo y del chat de IA, para que puedas ver claramente qué parte del sistema genera una señal empresarial real.',
    'dashboard.tour.step_next_action_title' => 'Tu próximo paso',
    'dashboard.tour.step_next_action_text' => 'Este bloque te ofrece una recomendación clara sobre qué hacer ahora. El objetivo de FCC no es abrumarte con datos, sino ayudarte a elegir el siguiente paso más útil.',
    'dashboard.tour.step_support_title' => 'Temas de apoyo y seminarios web',
    'dashboard.tour.step_support_text' => 'Aquí puedes abrir solicitudes de asistencia, leer las respuestas de los administradores y proponer temas para los seminarios web que quieras que tratemos. Forma parte de la formación de FCC y puede ayudarte cuando te encuentres con dificultades o quieras profundizar en algún tema.',
