    'fcc_results.homepage_spotlight_notice_after' => 'En la página ves las aplicaciones principales públicas que alcanzan 15 o más en 30 días. Cuando un colaborador alcanza 50 o más en 30 días, pasa al círculo recomendado de patrocinadores destacado en la página de inicio, siempre que la visualización pública esté activada y aprobada por el administrador.',
    'fcc_results.proof_note' => 'FCC Results muestra las métricas de actividad. Featured Apps son ejemplos públicos de 15+ / 30d, mientras que 50+ / 30d refuerza aún más el camino hacia patrocinadores recomendados en la página de inicio.',
    'fcc_results.metrics_note' => 'Los umbrales y las clasificaciones cuentan las visitas calificadas a Forever a través de botones y blogs generales y específicos, con protección contra visitas repetidas. Una etiqueta UTM por sí sola no suma puntos. La contribución de calificación del embudo VIP se muestra por separado; los contactos de otros embudos y del chat con IA indican interés.',
    'fcc_results.metrics_info.title' => 'Cómo se calcula',
    'fcc_results.metrics_info.position' => 'Posición: tu lugar en la lista según los clics cualificados durante el periodo seleccionado (7 o 30 días).',
    'fcc_results.metrics_info.shop_clicks' => 'Clics cualificados: clics únicos en los bloques de Forever Living y de tiendas web de las aplicaciones FCC, además de clics únicos del blog a Forever con tus etiquetas de recomendación y UTM.',
    'fcc_results.metrics_info.total_contacts' => 'Contactos: suma total de contactos del embudo y contactos del chat de IA durante el periodo seleccionado.',
    'fcc_results.metrics_info.ctr' => 'Muestra qué proporción de visitantes de tu aplicación FCC hace clic en al menos un botón u oferta clave.',
    'fcc_results.metrics_info.trend' => 'Tendencia: cambio en los clics que cumplen los requisitos en comparación con el periodo anterior de la misma duración.',
    'fcc_results.metrics_info.to_qualification' => 'Para la calificación: cuántos clics calificados faltan para alcanzar el umbral de 15.',
    'fcc_results.metrics_info.to_next_rank' => 'Para alcanzar el siguiente rango: cuántos clics cualificados necesitas para superar al usuario que está justo por encima de ti.',
    'fcc_results.tips.title' => 'Cómo alcanzar el siguiente nivel',
    'fcc_results.tips.subheader' => 'Realiza 1-2 acciones pequeñas esta semana para aumentar tus posibilidades de entrar en la lista o subir puestos.',
    'fcc_results.tips.item_1' => 'Publica tu aplicación Forever Card en las redes sociales y añade una llamada a la acción clara.',
    'fcc_results.tips.item_2' => 'Envía tu aplicación Forever Card a tus clientes actuales para que puedan usarla en su próximo pedido.',
    'fcc_results.tips.item_3' => 'Sube el bloque de la tienda en línea en tu aplicación para que se vea de inmediato.',
    'fcc_results.tips.item_4' => 'Añade una frase breve encima del botón de la tienda en línea, por ejemplo: «Ver los productos que recomiendo».',
    'fcc_results.tips.item_5' => 'Usa tu tarjeta NFC física durante las conversaciones con conocidos para presentar productos recomendados con un solo toque rápido.',
    'fcc_results.tips.item_6' => 'Comparte un producto de tu blog a través del enlace para compartir en una historia o envíalo directamente en un mensaje a contactos interesados para aumentar las visitas a Forever Shop con tu recomendación.',
    'fcc_results.tips.item_7' => 'Activa el asesor de IA en tu aplicación y guía a los visitantes para que inicien una conversación, porque los contactos recopilados por la IA también cuentan en tus resultados de contactos.',
