    'fcc_results.ai_widget.active_benefits' => 'A los 15 años desbloqueas un ritmo de IA más intenso dentro de Your growth plan: un plan semanal activo y una revisión periódica de la aplicación de IA.',
    'fcc_results.ai_widget.vip_benefits' => 'Al llegar a 50, pasas a un estado más destacado en la página de inicio y en la sección de patrocinadores recomendados. Esto cuenta como una señal de continuidad y experiencia dentro de FCC.',
    'fcc_results.ai_widget.pro_note' => 'Tu plan de crecimiento y FCC Results utilizan la misma señal de calificación para los umbrales de 15+ y 50+. Los contactos por WhatsApp y el chat con IA aportan contexto adicional sobre el interés, pero no suman puntos para estos umbrales.',
    'fcc_results.ai_widget.pro_required_note' => 'Para desbloquear todo el flujo de IA dentro de Tu plan de crecimiento, necesitas un paquete Pro activo. Aquí todavía puedes ver el progreso de tu señal calificada.',
    'fcc_results.ai_widget.featured_note_7d' => 'Con 15 o más en 30 días, apareces en la lista de aplicaciones destacadas; con 50 o más en 30 días, avanzas hacia la categoría de patrocinadores recomendados en la página de inicio. Esta vista de 7 días sirve únicamente para comprobar el ritmo semanal.',
    'fcc_results.ai_widget.featured_note_7d_unlocked' => 'Ya tienes 50 o más en 30 días y estás en una zona de patrocinio recomendada más sólida. Si también tienes 15 o más en 7 días, confirmas un ritmo semanal estable.',
    'fcc_results.ai_widget.featured_note_7d_experience' => 'Tienes 50 o más en 30 días y 15 o más confirmados en 7 días. Esto es una señal sólida para los patrocinadores recomendados y para mantener un ritmo semanal estable.',
