    'ai_plan.signal_summary.signal_label' => 'Señal actual',
    'ai_plan.signal_summary.signal_text_default' => 'Hay algunos indicios, pero todavía no son lo bastante sólidos como para convertirse en un resultado estable sin un enfoque más preciso.',
    'ai_plan.signal_summary.signal_text_zero' => 'Todavía no hay señales reales de la tienda web de Forever. El primer objetivo no es añadir más complejidad, sino conseguir los primeros clics de calidad que tengan sentido.',
    'ai_plan.signal_summary.signal_text_building' => 'Ahora tienes %s clics en Forever Webshop en los últimos 30 días. Necesitas al menos %s para que el plan semanal se base en señales reales en lugar de suposiciones.',
    'ai_plan.signal_summary.signal_text_ready' => 'Tienes %s clics en Forever Webshop durante los últimos 30 días, lo que significa que el sistema ya puede crear el plan semanal a partir del comportamiento real de los visitantes.',
    'ai_plan.signal_summary.action_label' => 'La acción más útil en este momento',
    'ai_plan.signal_summary.action_text_default' => 'Mantén un enfoque concreto: un mensaje claro, una dirección principal y una aplicación que realmente vayas a usar esta semana.',
    'ai_plan.signal_summary.action_text_direct' => 'El origen de las visitas no está claro con demasiada frecuencia. Esta semana, no disperses tus esfuerzos. Usa un formato que puedas repetir y una ruta clara hacia Forever Shop.',
    'ai_plan.signal_summary.action_text_recruitment' => 'Si tu enfoque es el negocio, usa una historia clara y una invitación a conversar esta semana, en lugar de insistir con demasiados mensajes y ofertas a la vez.',
    'ai_plan.signal_summary.action_text_building' => 'La prioridad es conseguir los primeros clics de calidad en Forever Webshop mediante una actividad repetible, no empezar varias ideas al mismo tiempo.',
    'ai_plan.signal_summary.action_text_funnel_live' => 'En este momento, %s de %s pasos de venta están activos. Esta semana, el objetivo debe ser mantener el recorrido claro para que la persona visitante no tenga que elegir demasiadas cosas a la vez.',
    'ai_plan.signal_summary.action_text_sales_ready' => 'La señal es lo bastante sólida como para que esta semana te centres en convertir el interés en acciones en la tienda web, no solo en conseguir más visitas.',
    'ai_plan.signal_summary.action_text_weekly_ready' => 'La señal está lista. El seguimiento semanal ahora es importante porque el plan ya no parte de suposiciones, sino del comportamiento real de los visitantes.',
    'ai_plan.signal_summary.watch_label' => 'Qué observar atentamente',
    'ai_plan.signal_summary.watch_text_default' => 'No hagas que la aplicación ni tus actividades semanales sean más complejas de lo que permite la señal actual. La claridad importa más que la amplitud.',
    'ai_plan.signal_summary.watch_text_mobile' => 'La mayoría de las personas ve tu página desde el teléfono. La primera pantalla, el primer mensaje y el primer clic deben ser evidentes de inmediato, sin tener que desplazarse demasiado ni elegir entre demasiadas opciones.',
    'ai_plan.signal_summary.watch_text_funnel_early' => 'Ya hay pasos de venta, pero la señal sigue siendo débil. No compliques demasiado el recorrido demasiado pronto si todavía no hay suficientes clics de calidad.',
    'ai_plan.signal_summary.watch_text_country' => 'Actualmente, la mayor parte del interés proviene de este mercado: %s. Asegúrate de que el mensaje, el ejemplo y la oferta sean claros para ese público.',
