    'featured_apps.header' => 'Forever Card Apps destacadas',
    'featured_apps.subheader' => 'Esta página muestra las principales aplicaciones públicas de FCC de colaboradores que han alcanzado la señal 15+ en los últimos 30 días. Quienes también alcanzan 50+ en 30 días refuerzan su posición para aparecer entre los patrocinadores recomendados en la página de inicio, mientras que 15+ en 7 días sigue siendo solo una comprobación del ritmo.',
