    'index.presentation1.header' => 'Forever Card App',
    'index.presentation1.subheader' => 'Cada socio recibe una aplicación personal que controla. Incluye video, productos, un asesor de IA, pedidos sin registro y todas las herramientas para desarrollar el negocio.',
