    'index.presentation4.feature5' => 'Cumple con GDPR, CCPA y PECR',
    'index.presentation5.header' => 'Convierte el interés en un negocio real',
    'index.presentation5.subheader' => 'Con FCC Funnel, recopilas contactos con más facilidad, haces seguimiento más rápido y ves claramente qué te genera más consultas, clientes potenciales y nuevos miembros del equipo.',
    'index.presentation5.feature1' => 'Recopilación más fácil de contactos interesados',
    'index.presentation5.feature2' => 'Comunicación más rápida y seguimiento más sencillo',
    'index.presentation5.feature3' => 'Mayor visibilidad y organización de los clientes potenciales',
    'index.presentation5.feature4' => 'Más oportunidades para hacer crecer tu negocio y tu equipo',
    'index.presentation6.header' => 'Asistentes de IA para recomendaciones de productos',
    'index.presentation6.subheader' => 'Los asistentes inteligentes de IA ayudan a las personas a encontrar rápidamente productos Forever para sí mismas, sus familias y sus mascotas, y a la vez generan más conversaciones y oportunidades de venta para ti.',
    'index.presentation6.feature1' => 'Recomendaciones de productos para personas y animales',
