    'index.stats.note' => 'Todo se puede medir: descubre en qué hacen clic las personas y de dónde surge el interés.',
    'index.shortener_app_linking.header' => 'URL que abren aplicaciones automáticamente',
    'index.shortener_app_linking.subheader' => 'Enlaces cortos que detectan automáticamente la aplicación utilizada y la abren en el móvil.',
    'index.domains.header' => 'Dominios personalizados',
    'index.domains.subheader' => 'Conecta tu propio dominio o usa los que ofrecemos.',
    'index.projects.header' => 'Proyectos',
    'index.projects.subheader' => 'La forma más sencilla de categorizar los recursos que administras.',
    'index.file_links.header' => 'Enlaces a archivos',
    'index.file_links.subheader' => 'Genera enlaces dinámicos, avanzados y descargables a archivos.',
    'index.vcard_links.header' => 'Tarjeta de presentación digital',
    'index.vcard_links.subheader' => 'Crea tarjetas de contacto digitales dinámicas, con seguimiento y descargables.',
    'index.splash_pages.header' => 'Páginas de destino',
    'index.splash_pages.subheader' => 'Usa páginas intermedias personalizadas con cuentas regresivas para tus enlaces.',
    'index.pixels.header' => 'Analítica avanzada y seguimiento del rendimiento',
    'index.pixels.subheader' => 'Todos los enlaces inteligentes y la aplicación Forever Card se integran con las principales plataformas de análisis y publicidad.',
    'index.pixels.note' => 'Los datos de seguimiento permiten a los socios entender qué funciona: qué contenido genera interés, de dónde vienen los visitantes y qué campañas dan resultados. El sistema admite la integración con los principales proveedores de píxeles y seguimiento.',
    'index.pricing.header' => 'Precios sencillos y transparentes.',
    'index.testimonials.one.text' => 'Esta plataforma transformó por completo la manera en que gestionamos nuestros flujos de trabajo. Es intuitiva y rápida, y le ha ahorrado a nuestro equipo incontables horas cada semana.',
    'index.testimonials.one.attribute' => 'Editora, Writer\'s Weekly',
    'index.testimonials.two.text' => 'Al principio tenía mis dudas, pero en pocos días vi cuánto más productivo se había vuelto nuestro equipo. Además, el equipo de soporte responde con muchísima rapidez.',
    'index.partners.header' => 'Por qué los miembros usan Forever Card Club',
    'index.partners.subheader' => 'Un sistema digital estructurado para desarrollar un negocio Forever profesional y global.',
    'index.partners.card1.title' => 'Un sistema: todo en un solo lugar',
    'index.partners.card1.text' => 'Aplicación personal, enlaces inteligentes, formación, asistencia con IA y análisis, todo integrado en un único ecosistema digital.',
    'index.partners.card2.title' => 'Enrutamiento global sin complejidad',
    'index.partners.card2.text' => 'Los enlaces inteligentes detectan automáticamente el país de la persona visitante y la conectan con la tienda web oficial de Forever de su región.',
    'index.partners.card3.title' => 'Presencia profesional en línea y fuera de línea',
    'index.partners.card3.text' => 'La aplicación personal y la tarjeta NFC permiten compartir fácilmente sin conocimientos técnicos.',
    'index.partners.card4.title' => 'Estructura clara para crecer',
    'index.partners.card4.text' => 'Un plan estructurado de 120 días y una formación paso a paso ayudan a los socios a crear un sistema estable y escalable.',
    'index.faq.header' => 'Respuestas a preguntas frecuentes',
    'index.faq.one.question' => '¿Cómo consigo mi aplicación Forever Card?',
    'index.faq.one.answer' => 'Recibes tu Forever Card App cuando te conviertes en socio comercial Forever registrado y tu patrocinador forma parte de nuestro equipo. Una vez concedido el acceso, sigues un sencillo proceso de incorporación que te muestra cómo activar y configurar tu aplicación personal. Tu aplicación es tu base digital: eliges qué bloques mostrar, por ejemplo, video, productos, asesor de IA, contacto y formación, y puedes configurarlo todo sin conocimientos técnicos. Si también trabajas sin conexión, recibes gratis una tarjeta NFC en tu domicilio, que abre tu aplicación con un rápido toque o escaneo.',
    'index.faq.two.question' => '¿Cómo funcionan los pedidos sin registro y las referencias?',
    'index.faq.two.answer' => 'Forever Card Club utiliza enlaces de referencia inteligentes diseñados para compartirse en todo el mundo. Cuando un visitante hace clic en tu enlace o selecciona un producto dentro de tu aplicación y elige «pedir», el sistema puede detectar automáticamente el país del visitante y conectarlo con la tienda web oficial de Forever de su país. Tu referencia está integrada en el enlace, de modo que la compra puede asociarse contigo como socio recomendador, de acuerdo con las reglas del sistema oficial. Importante: Forever Card Club no vende productos. Todas las compras se realizan a través de la tienda web oficial del país del cliente.',
    'index.faq.three.question' => '¿Qué recibo como miembro del equipo?',
    'index.faq.three.answer' => 'Como miembro del equipo, recibes un sistema completo para crear un negocio Forever en línea, que incluye: una Forever Card App personal (tus herramientas y contenido en un solo lugar), enlaces de recomendación inteligentes para dirigir a las personas de todo el mundo a la tienda web oficial, un asesor de IA para orientación e información sobre productos dentro de la aplicación, formación paso a paso (cómo usar el sistema y crear tu negocio en línea), un plan personalizado de 120 días, adaptado a tus hábitos y objetivos, análisis (qué enlaces pulsa la gente, de dónde viene y qué funciona mejor) y una tarjeta NFC gratuita enviada a tu domicilio para los contactos en persona. También recibes apoyo de la comunidad (por ejemplo, grupos de WhatsApp y pautas claras) para ayudarte a mantener la constancia y obtener resultados a largo plazo.',
    'index.faq.four.question' => '¿Cómo funciona el plan de 120 días?',
    'index.faq.four.answer' => 'El plan de 120 días es un programa estructurado que guía a los partners desde la configuración inicial, pasando por la creación de hábitos, hasta establecer una rutina constante de comunicación en línea, recomendaciones y crecimiento del equipo y de la clientela. No es un PDF genérico. Está diseñado para adaptarse a cada persona: al tiempo disponible, el estilo de comunicación, el nivel de experiencia y los objetivos. El plan ofrece pasos claros sobre qué configurar en tu aplicación, cómo usar enlaces inteligentes, cómo presentar información en línea y cómo crear un sistema repetible que puedas replicar con tu futuro equipo.',
    'index.faq.five.question' => '¿Qué hace el asesor de IA dentro de la aplicación?',
    'index.faq.five.answer' => 'El asesor de IA ayuda a los visitantes a encontrar información con más facilidad. Según sus preguntas, puede sugerir información y productos pertinentes y guiarlos al siguiente paso, ya sea obtener más información, ponerse en contacto o hacer un pedido. Si el visitante decide hacer un pedido, el asesor de IA puede dirigirlo a la tienda web oficial mediante enlaces inteligentes, con la conexión de referencia del socio. Para los socios, reduce la necesidad de repetir información básica y ayuda a que la comunicación sea clara y coherente.',
    'index.faq.contact_note' => 'Si quieres acceder o tienes alguna pregunta, ponte en contacto a través de %s.',
    'index.faq.contact_link' => 'Página de contacto',
