    'links.header' => 'Enlaces',
    'links.subheader' => 'Crea y administra todos tus enlaces personalizados.',
    'links.short_links.guide_title' => 'Enlaces cortos, explicados justo donde las personas los necesitan',
    'links.short_links.guide_text' => 'Crea un enlace corto en segundos y luego usa Editar para definir cómo funciona. Esta vista ahora guía a las personas en la creación, la administración de listas, el análisis y la configuración avanzada de redireccionamiento, para que puedan usar cada opción con confianza.',
    'links.short_links.total_label' => 'Enlaces cortos activos',
    'links.short_links.guide_card_1_title' => 'Crea rápidamente',
    'links.short_links.guide_card_1_text' => 'Empieza con una URL de destino y, si quieres, establece un alias personalizado. Si lo dejas vacío, el sistema generará uno por ti.',
    'links.short_links.guide_card_2_title' => 'Edita con un propósito',
    'links.short_links.guide_card_2_text' => 'Abre Edit para controlar el seguimiento, las reglas temporales, la vinculación con aplicaciones, la protección con contraseña, el ocultamiento, la segmentación y otros comportamientos de redirección.',
    'links.short_links.guide_card_3_title' => 'Gestiona a gran escala',
    'links.short_links.guide_card_3_text' => 'Usa la importación masiva, los filtros, la copia, los códigos QR, la duplicación, el restablecimiento y los controles de estado para mantener organizada una biblioteca de enlaces amplia.',
    'links.short_links.guide_card_4_title' => 'Mide lo que funciona',
    'links.short_links.guide_card_4_text' => 'Consulta las estadísticas para ver qué enlaces cortos funcionan mejor y luego perfecciona tu configuración directamente desde la pantalla de edición.',
    'links.short_links.empty' => 'Ningún enlace corto coincide con los filtros actuales.',
    'links.short_links.empty_title' => 'Crea tu primer enlace corto',
    'links.short_links.empty_text' => 'Empieza con el botón URL acortada y luego abre Editar para acceder a las opciones de seguimiento, programación, segmentación, protección y marca.',
    'links.short_links.tour.create_title' => 'Crear un enlace corto',
    'links.short_links.tour.create_text' => 'Esta es la forma más rápida de añadir un enlace corto nuevo. Solo necesitas una URL de destino y, si quieres, también puedes definir un alias personalizado para que el enlace sea fácil de recordar.',
    'links.short_links.tour.bulk_title' => 'Importar o crear en bloque',
