    'qr_codes.title' => 'Códigos QR',
    'qr_codes.menu' => 'Códigos QR',
    'qr_codes.breadcrumb' => 'Códigos QR',
    'qr_codes.header' => 'Códigos QR',
    'qr_codes.subheader' => 'Crea fácilmente códigos QR personalizables y guárdalos para usarlos más adelante.',
    'qr_codes.page_intro' => 'Crea códigos QR independientes para imprimir, compartir sin conexión, eventos, productos, WiFi, intercambio de contactos y muchos otros casos. Cada Forever Card App también puede crear su propio código QR directo, mientras que esta sección te ofrece un espacio QR separado para crearlos y editarlos en un solo lugar.',
    'qr_codes.guide_title' => 'Un espacio de trabajo QR independiente para impresión, uso compartido sin conexión y casos de uso controlados',
    'qr_codes.guide_text' => 'Esta sección de QR es para recursos QR independientes que quieres gestionar fuera de una pantalla específica de la aplicación. Úsala cuando necesites códigos QR imprimibles, códigos de campaña reutilizables, puntos de acceso a eventos o productos, o un QR que merezca su propio estilo y proceso de exportación.',
    'qr_codes.guide_card_1_title' => 'Separado del código QR de la aplicación',
    'qr_codes.guide_card_1_text' => 'Cada Forever Card App puede generar su propio código QR directo, pero aquí puedes crear códigos QR totalmente independientes para otras páginas de destino, enlaces, materiales y campañas.',
    'qr_codes.guide_card_2_title' => 'Diseñado para imprimir y usar sin conexión',
    'qr_codes.guide_card_2_text' => 'Estos códigos QR son ideales para folletos, tarjetas de presentación, carteles, fichas de productos, mesas de eventos, envases y para compartir en persona, cuando la gente escanea en lugar de escribir.',
    'qr_codes.guide_card_3_title' => 'Personaliza y exporta correctamente',
    'qr_codes.guide_card_3_text' => 'Controla el tipo de QR, el estilo, los colores, los marcos, el logotipo, la imagen de marca y el formato del archivo para que el código final se adapte al contexto en el que se utilizará.',
    'qr_codes.guide_card_4_title' => 'Editar y reutilizar más adelante',
    'qr_codes.guide_card_4_text' => 'Una vez creado, cada código QR queda disponible para descargar, imprimir, duplicar y perfeccionar más adelante, sin tener que volver a crearlo desde cero.',
    'qr_codes.empty_title' => 'Crea tu primer código QR',
    'qr_codes.empty_text' => 'Empieza con un código QR independiente para un enlace, una aplicación, un contacto, un evento o material impreso. Después de crearlo, puedes volver para editar el estilo, el marco, la marca y el formato de exportación.',
    'qr_codes.tour.create_title' => 'Crear un código QR independiente',
    'qr_codes.tour.create_text' => 'Usa este botón cuando quieras crear un código QR que esté fuera de una página específica de Forever Card App. Es ideal para campañas, materiales impresos, eventos y para compartirlo sin conexión y reutilizarlo.',
    'qr_codes.tour.guide_title' => 'Comprende cuándo corresponde usar esta sección',
    'qr_codes.tour.guide_text' => 'Esta guía explica la diferencia entre los códigos QR específicos de la aplicación y los recursos QR independientes. El objetivo es ayudar a las personas usuarias a elegir el flujo adecuado antes de crear o editar.',
    'qr_codes.tour.list_title' => 'Aquí tu biblioteca de códigos QR se mantiene organizada',
    'qr_codes.tour.list_text' => 'Esta lista se convierte en el centro de control de cada código QR independiente: la vista previa, el nombre, el tipo, la relación con el proyecto, las opciones de exportación y el acceso para editar están todos en un mismo lugar.',
    'qr_codes.tour.row_title' => 'Cada fila es un recurso QR reutilizable',
    'qr_codes.tour.row_text' => 'Aquí, un código QR puede representar una URL, un enlace a una aplicación, un evento, una conexión WiFi, una vCard, una solicitud de pago u otras muchas experiencias de escaneo. Puedes seguir perfeccionando el mismo recurso con el tiempo.',
    'qr_codes.tour.actions_title' => 'Descargar, imprimir, editar, duplicar',
    'qr_codes.tour.actions_text' => 'Usa las acciones de la derecha para exportar en distintos formatos, abrir Edit, duplicar un código QR activo para una nueva campaña o eliminar los recursos antiguos que ya no necesites.',
