    'qr_code_update.breadcrumb' => 'Editar código QR',
    'qr_code_update.title' => 'Editar código QR',
    'qr_code_update.header' => 'Editar código QR',
    'qr_codes.editor.hero_title' => 'Convierte un código QR sencillo en un punto de acceso reutilizable del mundo físico al digital',
    'qr_codes.editor.hero_text' => 'Este editor es el lugar donde un código QR se vuelve práctico, personalizado y listo para usar. Cada Forever Card App puede generar su propio QR, pero aquí puedes crear y perfeccionar por separado códigos QR para imprimir, campañas, eventos, recorridos de productos, compartir contactos y muchos otros casos de uso de escaneo.',
    'qr_codes.editor.hero_card_1_title' => 'Elige el resultado del escaneo',
    'qr_codes.editor.hero_card_1_text' => 'Decide si el código QR debe abrir una URL, una tarjeta de contacto, un flujo de pago, una conexión WiFi, un borrador de mensaje, un evento, una ubicación u otra acción compatible.',
    'qr_codes.editor.hero_card_2_title' => 'Diseña para el contexto',
    'qr_codes.editor.hero_card_2_text' => 'Ajusta el estilo, los colores, el marco, la marca y el logotipo opcional para que el código QR se adapte a un volante, una tarjeta de presentación, una ficha de producto, una presentación o material para un evento.',
    'qr_codes.editor.hero_card_3_title' => 'Vista previa antes de imprimir',
    'qr_codes.editor.hero_card_3_text' => 'Usa la vista previa en tiempo real, la comprobación de legibilidad y las opciones de descarga para hacer pruebas antes de imprimir el QR o distribuirlo públicamente.',
    'qr_codes.editor.hero_card_4_title' => 'Reutiliza en lugar de crear de nuevo',
    'qr_codes.editor.hero_card_4_text' => 'Cuando un código QR funcione bien, sigue editándolo, duplicándolo o exportándolo para nuevas campañas, en lugar de empezar de nuevo cada vez.',
    'qr_codes.editor.tour.intro_title' => 'Descripción general del editor de QR',
    'qr_codes.editor.tour.intro_text' => 'Esta página te ayuda a crear o perfeccionar un código QR independiente que puedes imprimir, compartir, exportar y reutilizar en muchos contextos.',
    'qr_codes.editor.tour.type_title' => 'Elige qué debe hacer el escaneo',
    'qr_codes.editor.tour.type_text' => 'El tipo de QR define el resultado concreto para quien lo escanea: abrir un enlace, guardar datos de contacto, iniciar un mensaje, conectarse a una red WiFi, mostrar una solicitud de pago y mucho más.',
    'qr_codes.editor.tour.basics_title' => 'Empieza con el nombre y los datos principales',
    'qr_codes.editor.tour.basics_text' => 'Ponle al código QR un nombre interno claro y completa los campos de contenido esenciales. Esta es la información principal que se incorporará al código.',
    'qr_codes.editor.tour.style_title' => 'Dale forma al patrón del código QR',
    'qr_codes.editor.tour.style_text' => 'El estilo controla la geometría de los módulos y los patrones de posición del código QR. Esto resulta útil cuando se quiere que el código QR coincida visualmente con una marca, una campaña o una pieza impresa.',
    'qr_codes.editor.tour.colors_title' => 'Controla el contraste y la facilidad de lectura del código',
    'qr_codes.editor.tour.colors_text' => 'Los colores no son solo una cuestión estética. Un buen contraste es fundamental para que el escaneo sea fiable, especialmente si el código QR se va a imprimir o se verá con una iluminación imperfecta.',
    'qr_codes.editor.tour.frame_title' => 'Añade contexto alrededor del código QR',
    'qr_codes.editor.tour.frame_text' => 'Los marcos ayudan a que un código QR se vea más intencional y permiten añadir una llamada a la acción o una etiqueta para que las personas entiendan de inmediato por qué deberían escanearlo.',
    'qr_codes.editor.tour.branding_title' => 'Añade el logotipo y las capas de marca con cuidado',
    'qr_codes.editor.tour.branding_text' => 'Las opciones de marca te permiten incluir logotipos e imágenes en la composición del código QR, pero deben probarse cuidadosamente para que la legibilidad siga siendo alta.',
    'qr_codes.editor.tour.options_title' => 'Finalizar los ajustes técnicos',
    'qr_codes.editor.tour.options_text' => 'El tamaño, el margen, la codificación, la corrección de errores y la organización del proyecto ayudan a que el código QR funcione correctamente al exportarlo y usarlo en producción.',
    'qr_codes.editor.tour.preview_title' => 'Mira el código QR final en directo',
    'qr_codes.editor.tour.preview_text' => 'En la vista previa puedes confirmar que el código QR se vea nítido y se pueda escanear antes de descargarlo, imprimirlo o compartirlo.',
    'qr_codes.editor.tour.download_title' => 'Preparar el resultado para imprimir o entregar',
    'qr_codes.editor.tour.download_text' => 'Exporta en SVG, PNG, JPG o WEBP según necesites calidad de impresión, transparencia, uso en presentaciones o distribución rápida.',
    'qr_codes.editor.tour.save_title' => 'Guarda, prueba y luego publica',
    'qr_codes.editor.tour.save_text' => 'Después de guardar, escanea el código QR con al menos un teléfono antes de usarlo públicamente. Esto es especialmente importante si se utilizan marcos, degradados, logotipos o materiales impresos.',
    'biolink_block_delete.header' => 'Eliminar bloque',
    'biolink_block_delete.subheader' => 'Se eliminarán por completo todos los datos relacionados con el bloque de FCC. Esta acción no se puede deshacer.',
    'biolink_block_delete.success_message' => 'El bloque de FCC se eliminó correctamente.',
    'biolink_block.title' => 'Bloque FCC',
