    'link.header.subheader' => 'Aplicación Forever Card: %s',
    'link.header.short_link_subheader' => 'Configuración del enlace corto: %s',
    'link.short_editor.hero_title' => 'Convierte una URL corta sencilla en un flujo de redirección controlado',
    'link.short_editor.hero_text' => 'En este editor, un enlace corto se convierte en una herramienta estratégica. Además del alias y el destino, puedes añadir programación, seguimiento UTM, protección con contraseña, enlaces a aplicaciones, ocultación de enlaces, segmentación por dispositivo o ubicación, comportamiento HTTP y otros controles avanzados.',
    'link.short_editor.hero_card_1_title' => 'Empieza por lo básico',
    'link.short_editor.hero_card_1_text' => 'Define la URL de destino, elige el alias corto y decide qué dominio debe usar el enlace corto.',
    'link.short_editor.hero_card_2_title' => 'Decide cómo se comporta',
    'link.short_editor.hero_card_2_text' => 'Controla cuándo funciona el enlace, a dónde redirige, qué ocurre al caducar y si debe transferir los parámetros de consulta.',
    'link.short_editor.hero_card_3_title' => 'Rastrea y personaliza',
    'link.short_editor.hero_card_3_text' => 'Añade etiquetas UTM, píxeles, metadatos de encubrimiento y enlaces a aplicaciones para que cada clic incluya el contexto que necesitas.',
    'link.short_editor.hero_card_4_title' => 'Proteger y optimizar',
    'link.short_editor.hero_card_4_text' => 'Usa contraseñas, advertencias de contenido sensible, segmentación de audiencia y códigos de redirección para adaptar cada campaña a su público.',
    'link.short_editor.form_title' => 'Qué puedes configurar en un enlace corto',
    'link.short_editor.form_text' => 'Abre solo las secciones que necesites o sigue el tutorial paso a paso. Cada grupo que aparece a continuación controla una capa de la experiencia de los enlaces cortos, desde las redirecciones sencillas hasta la lógica avanzada de campañas.',
    'link.short_editor.card_1_title' => 'Para lanzamientos claros',
    'link.short_editor.card_1_text' => 'Configura el destino, el alias, el dominio y el código de redirección para que el enlace funcione exactamente como quieres desde la primera vez que lo compartas.',
    'link.short_editor.card_2_title' => 'Para campañas e informes',
    'link.short_editor.card_2_text' => 'Añade valores UTM, píxeles, informes y proyectos para medir y agrupar correctamente el tráfico.',
    'link.short_editor.card_3_title' => 'Para un comportamiento avanzado',
    'link.short_editor.card_3_text' => 'Programa la disponibilidad, establece reglas de caducidad, protege el acceso, define el público destinatario u oculta la página de destino cuando sea necesario.',
    'link.short_editor.tour.intro_title' => 'Descripción general del editor de enlaces cortos',
    'link.short_editor.tour.intro_text' => 'Esta página reúne todas las opciones avanzadas de un enlace corto. El objetivo es sencillo: ayudar a las personas a entender qué cambia cada ajuste antes de guardarlo.',
    'link.short_editor.tour.basics_title' => 'Primero, lo básico',
    'link.short_editor.tour.basics_text' => 'Aquí defines a dónde dirige el enlace corto, qué alias usa y en qué dominio debe alojarse. Estos son los ajustes básicos de redirección.',
    'link.short_editor.tour.app_linking_title' => 'Abrir aplicaciones móviles directamente',
    'link.short_editor.tour.app_linking_text' => 'Los enlaces a aplicaciones permiten que los destinos móviles compatibles se abran dentro de la aplicación nativa, en lugar de hacerlo solo en el navegador, lo que puede mejorar la experiencia de uso en teléfonos.',
    'link.short_editor.tour.temporary_title' => 'Establece reglas de duración y vencimiento',
    'link.short_editor.tour.temporary_text' => 'Usa esta sección para programar la disponibilidad, limitar los clics o definir adónde se dirige a las personas cuando vence el enlace. Es ideal para promociones, lanzamientos y campañas con plazos definidos.',
    'link.short_editor.tour.utm_title' => 'Añadir contexto de analítica',
    'link.short_editor.tour.utm_text' => 'Los parámetros UTM ayudan a las herramientas de análisis a identificar la fuente, el medio y la campaña del tráfico. Este es uno de los lugares más útiles para estandarizar los nombres de tus campañas.',
    'link.short_editor.tour.protection_title' => 'Proteger el acceso cuando sea necesario',
    'link.short_editor.tour.protection_text' => 'Las contraseñas y las advertencias sobre contenido sensible son útiles cuando un enlace no debe estar completamente abierto o cuando los visitantes necesitan contexto antes de continuar.',
    'link.short_editor.tour.targeting_title' => 'Dirige a diferentes públicos a destinos distintos',
    'link.short_editor.tour.targeting_text' => 'La segmentación permite que un enlace corto responda a reglas de país, ciudad, dispositivo, sistema operativo, idioma del navegador o rotación. Esto es muy útil para campañas segmentadas.',
    'link.short_editor.tour.cloaking_title' => 'Controla la vista previa que ven las personas',
    'link.short_editor.tour.cloaking_text' => 'El cloaking cambia el título, la descripción, la imagen y otros metadatos que se muestran antes de la redirección. Es útil cuando la vista previa compartida debe coincidir con el mensaje de la campaña.',
    'link.short_editor.tour.http_title' => 'Elige el tipo de redirección',
    'link.short_editor.tour.http_text' => 'Los códigos 301, 302, 307 y 308 no son idénticos. Esta sección determina si la redirección se considera permanente o temporal y cómo deben tratarla los navegadores.',
    'link.short_editor.tour.advanced_title' => 'Termina con los controles avanzados',
    'link.short_editor.tour.advanced_text' => 'Aquí encontrarás proyectos, páginas de inicio, notificaciones, reenvío de consultas y opciones relacionadas para integrar el enlace corto en un flujo de trabajo más amplio.',
    'link.short_editor.tour.save_title' => 'Guardar y probar',
    'link.short_editor.tour.save_text' => 'Después de guardar, prueba el enlace corto en computadora y móvil, y consulta las estadísticas para confirmar que las redirecciones, la atribución y la segmentación funcionen como esperas.',
