    'global.emails.admin.fcc_access_approved.subject' => 'Se ha aprobado tu acceso a Forever Card Club.',
    'global.emails.admin.fcc_access_approved.body' => 'Hola {{NAME}}, <br /><br />

Se ha aprobado tu acceso a <strong>Forever Card Club</strong>. Ahora puedes iniciar sesión, explorar el sistema y familiarizarte con las herramientas que ya tienes disponibles. <br /><br />

<div style="padding:18px 20px;border-radius:16px;background:linear-gradient(135deg,#0f2440 0%,#153a4d 100%);border:1px solid rgba(83,214,206,0.28);margin:18px 0;">
    <div style="font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:#9de7e0;margin-bottom:8px;">Tu acceso a FCC</div>
    <div style="color:#ffffff;line-height:1.75;">
        <strong>Aplicación principal de Forever Card:</strong> {{APP_LINK}} <br />
        <strong>Panel:</strong> {{DASHBOARD_LINK}}
    </div>
</div>

Dentro de FCC, ya puedes empezar a editar tu aplicación principal, entender cómo funciona el sistema y ver cómo se conectan los contenidos, las recomendaciones y las herramientas en un flujo de negocio. <br /><br />

Si quieres aprovechar todo el potencial de configuración para tu negocio en línea, también tienes la opción de activar <strong>Forever Pro</strong> con un <strong>período de prueba de 30 días</strong>. Esto te da acceso al sistema completo de IA, al seguimiento de señales de negocio, a la planificación semanal, a herramientas avanzadas de ventas y embudos, y a una configuración más automatizada para toda tu presencia en línea. <br /><br />

Al activar este período de prueba, también podrás recibir una <strong>tarjeta NFC física sin costo</strong>, enviada a tu domicilio. Con un toque, la tarjeta abre tu aplicación principal de Forever Card. <br /><br />

No es una obligación, sino una oportunidad para probar con calma el sistema completo durante 30 días y ver cuánto puede ayudarte a configurar y gestionar tu negocio. Si quieres, puedes consultar los detalles aquí: {{ACCOUNT_PLAN_LINK}} <br /><br />

Si tienes alguna pregunta, no dudes en contactarnos. <br /><br />

Saludos cordiales, <br />
{{WEBSITE_TITLE}}',
    'global.emails.admin.fcc_access_rejected.subject' => 'No se aprobó el acceso a Forever Card Club / Pristup Forever Card Clubu nije odobren.',
    'global.emails.admin.fcc_access_rejected.body' => 'Hola {{NAME}}, <br /><br />

tras una revisión manual, no se ha aprobado tu solicitud de acceso a <strong>Forever Card Club</strong> y tu cuenta se ha eliminado del sistema. <br /><br />

<div style="padding:18px 20px;border-radius:16px;background:linear-gradient(135deg,#3b1822 0%,#24131f 100%);border:1px solid rgba(255,167,167,0.24);margin:18px 0;color:#fff4f4;">
    <div style="font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:#ffb9b9;margin-bottom:8px;">Motivos más comunes / Najčešći razlozi</div>
    <div style="line-height:1.75;">
       : el número de <strong>Forever ID</strong> indicado no es válido <br />
       : no se ha confirmado que formes parte de nuestro equipo <br /><br />
       : upisani <strong>Forever ID</strong> broj Forever Living Productsa je neispravan <br />
       : članstvo nije potvrđeno kao dio našeg tima
    </div>
</div>

En este momento, el acceso está reservado exclusivamente a los miembros de la estructura Forever de los Diamond Sapphire Managers <strong>Snježana y Stjepan Beloša</strong>. <br /><br />

Si crees que se te ha denegado el acceso por error, puedes enviar una consulta o reclamación a {{CONTACT_EMAIL}}. <br /><br />

Gracias por tu comprensión. <br /><br />

Un cordial saludo, <br />
{{WEBSITE_TITLE}}

<hr style="border:none;border-top:1px solid rgba(255,255,255,0.14);margin:24px 0;" />

Poštovani/a {{NAME}}, <br /><br />

nakon ručne provjere Vaš zahtjev za pristup <strong>Forever Card Clubu</strong> trenutno nije odobren, a Vaš račun je uklonjen iz sustava. <br /><br />

Trenutni pristup imaju isključivo članovi Forever strukture Diamond Saphir managera <strong>Snježane i Stjepana Beloše</strong>. <br /><br />

Ako smatrate da je pristup odbijen pogreškom, upit ili prigovor možete poslati na {{CONTACT_EMAIL}}. <br /><br />

Hvala na razumijevanju. <br /><br />

Lijep pozdrav, <br />
{{WEBSITE_TITLE}}',
    'global.emails.admin.fcc_access_rejected_not_team.subject' => 'No se aprobó el acceso a FCC, pero Force Click está disponible / No se aprobó el acceso a FCC, pero Force Click está disponible.',
    'global.emails.admin.fcc_access_rejected_not_team.body' => 'Hola {{NAME}}, <br /><br />

gracias por registrarte en <strong>Forever Card Club</strong>. Después de una revisión manual, no podemos aprobar tu acceso a FCC en este momento porque Forever Card Club es una plataforma privada destinada a los miembros de la estructura Forever de los Diamond Sapphire Manager <strong>Snježana y Stjepan Beloša</strong>. <br /><br />

Tu cuenta de Forever Card Club se ha eliminado del sistema. <br /><br />

Si quieres usar herramientas en línea similares para tu negocio Forever, te recomendamos <strong>Force Click</strong>, nuestra plataforma hermana, disponible para un grupo más amplio de asociados Forever. <br /><br />

<div style="padding:18px 20px;border-radius:16px;background:linear-gradient(135deg,#0f2440 0%,#153a4d 100%);border:1px solid rgba(83,214,206,0.28);margin:18px 0;">
    <div style="font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:#9de7e0;margin-bottom:8px;">Force Click for Forever / Force Click za Forever</div>
    <div style="color:#ffffff;line-height:1.75;">
        Presentación de productos en línea, enlaces de venta, promoción QR/NFC, contenido y una presencia digital más sencilla. <br />
        Online prezentacija proizvoda, prodajni linkovi, QR/NFC promocija, sadržaj i jednostavniji digitalni nastup. <br /><br />
        {{FORCE_CLICK_LINK}}
    </div>
</div>

Si crees que tu acceso a FCC se rechazó por error, puedes enviar una consulta o reclamación a {{CONTACT_EMAIL}}. <br /><br />

Gracias por tu comprensión. <br /><br />

Saludos cordiales, <br />
{{WEBSITE_TITLE}}

<hr style="border:none;border-top:1px solid rgba(255,255,255,0.14);margin:24px 0;" />

Poštovani/a {{NAME}}, <br /><br />

hvala Vam na registraciji za <strong>Forever Card Club</strong>. Nakon ručne provjere FCC pristup Vam trenutno ne možemo odobriti jer je Forever Card Club privatna platforma namijenjena članovima Forever strukture Diamond Saphir managera <strong>Snježane i Stjepana Beloše</strong>. <br /><br />

Vaš račun na Forever Card Clubu je uklonjen iz sustava. <br /><br />

Ako želite koristiti slične online alate za Forever poslovanje, preporučujemo <strong>Force Click</strong>, našu sestrinsku platformu otvorenu za širi krug Forever suradnika. <br /><br />

Force Click stranicu za Forever Living Products možete otvoriti ovdje: {{FORCE_CLICK_LINK}} <br /><br />

Ako smatrate da je pristup FCC-u odbijen pogreškom, upit ili prigovor možete poslati na {{CONTACT_EMAIL}}. <br /><br />

Hvala na razumijevanju. <br /><br />

Lijep pozdrav, <br />
{{WEBSITE_TITLE}}',
    'global.emails.admin.card_sent_email.subject' => 'Tu tarjeta NFC de cortesía ha sido enviada.',
    'global.emails.admin.card_sent_email.body' => 'Hola {{NAME}}, <br /><br />

Tras la activación de tu plan <strong>Forever Pro</strong>, hemos enviado a tu dirección por correo certificado tu <strong>tarjeta NFC</strong> de cortesía. <br /><br />

<div style="padding:18px 20px;border-radius:16px;background:linear-gradient(135deg,#11253d 0%,#123b40 100%);border:1px solid rgba(101,225,201,0.24);margin:18px 0;">
