    'fcc.page.semantics_heading' => '¿Qué es Forever Card Club (FCC)?',
    'fcc.page.semantics_summary' => 'Forever Card Club (FCC) es un sistema digital integral para los socios de Forever Living Products. FCC combina una aplicación personal, enlaces inteligentes de recomendación, asistentes de productos con IA, lógica de embudos de captación, formación, análisis y una tarjeta física NFC en un único flujo de trabajo empresarial.',
    'fcc.page.semantics_fact_1' => 'Forever Card Club no es un sitio web ni una tienda oficial de Forever Living Products, sino un sistema independiente para socios.',
    'fcc.page.semantics_fact_2' => 'La aplicación Forever Card es la aplicación personal que recibe cada miembro, mientras que FCC se refiere al sistema más amplio.',
    'fcc.page.semantics_fact_3' => 'Las compras de productos se realizan en la tienda web oficial de Forever del país del cliente.',
    'fcc.page.semantics_fact_4' => 'El sistema está diseñado para compartir en línea, dirigir referidos, captar contactos potenciales, ofrecer orientación con IA y hacer crecer el negocio Forever.',
    'fcc.page.semantics_solves_heading' => '¿Qué resuelve FCC?',
    'fcc.page.semantics_solve_1' => 'Un lugar central para la aplicación para socios, el contenido, los productos y las acciones de contacto.',
    'fcc.page.semantics_solve_2' => 'Derivación más inteligente a la tienda oficial de Forever del país del visitante.',
    'fcc.page.semantics_solve_3' => 'Captación de prospectos y seguimiento más rápido tras un interés o una recomendación.',
    'fcc.page.semantics_solve_4' => 'Descubrimiento de productos guiado por IA y orientación sobre los próximos pasos dentro del sistema.',
    'fcc.page.semantics_solve_5' => 'Un puente claro desde el contacto presencial, a través de NFC/QR, hasta el flujo de trabajo en línea.',
    'fcc.page.term_description' => 'Forever Card Club (FCC) es un sistema digital integral para los socios de Forever Living Products que incluye una aplicación personal, enlaces inteligentes de recomendación, asistentes de productos con IA, lógica de embudos de clientes potenciales, formación, analíticas y una tarjeta física NFC vinculada al contenido y las recomendaciones del socio.',
    'fcc.page.workflow_heading' => '¿Cómo funciona FCC en la práctica?',
    'fcc.page.workflow_intro' => 'Desde captar la atención inicial hasta el contacto o la compra, FCC conecta los pasos clave en un único flujo de negocio.',
    'fcc.page.workflow_step_1_title' => 'Entrada',
    'fcc.page.workflow_step_1_text' => 'Una publicación, un mensaje, un código QR o una tarjeta NFC lleva al visitante al sistema.',
    'fcc.page.workflow_step_2_title' => 'App',
    'fcc.page.workflow_step_2_text' => 'La aplicación Forever Card abre contenido, productos, acciones de contacto y recomendaciones.',
    'fcc.page.workflow_step_3_title' => 'Orientación',
    'fcc.page.workflow_step_3_text' => 'La IA, los enlaces y los bloques orientan al visitante hacia el siguiente paso adecuado.',
    'fcc.page.workflow_step_4_title' => 'Acción',
    'fcc.page.workflow_step_4_text' => 'El visitante deja sus datos de contacto o avanza hacia la tienda oficial de Forever.',
    'fcc.page.workflow_step_5_title' => 'Seguimiento',
    'fcc.page.workflow_step_5_text' => 'El socio hace seguimiento del interés y continúa la conversación con más facilidad.',
    'fcc.page.use_cases_heading' => '¿Qué resuelve FCC?',
    'fcc.page.use_cases_intro' => 'El mismo sistema permite desarrollar un negocio Forever de varias maneras diferentes.',
