    'fcc_ai.platform.title' => 'Descripción general de la plataforma',
    'fcc_ai.platform.note_admin' => 'Los detalles técnicos siguen disponibles abajo en secciones desplegables, mientras la pantalla principal se mantiene despejada.',
    'fcc_ai.platform.note_user' => 'Consulta en un solo lugar cómo está habilitada la IA en la aplicación, cómo funciona Coach y dónde se registran las conversaciones y los clientes potenciales.',
    'fcc_ai.platform.list.app_blocks_title' => 'Bloques de IA en la aplicación',
    'fcc_ai.platform.list.app_blocks_text' => 'La IA pública se activa al añadir un bloque de IA en los ajustes de FCC App. Una vez añadido, la IA aparece en esa aplicación.',
    'fcc_ai.platform.list.coach_title' => 'FCC Coach',
    'fcc_ai.platform.list.coach_text' => 'Coach está siempre disponible dentro de FCC, conectado al plan de crecimiento y diseñado para apoyar la plataforma, las redes sociales, la comunicación y el desarrollo del negocio.',
    'fcc_ai.platform.list.single_ai_title' => 'Una IA por aplicación',
    'fcc_ai.platform.list.single_ai_text' => 'Solo puede haber un asesor de IA activo en cada FCC App. Si ya se ha añadido un bloque de IA, al añadir otro aparecerá una advertencia.',
    'fcc_ai.platform.list.leads_title' => 'Contactos potenciales de IA',
    'fcc_ai.platform.list.leads_text' => 'Los contactos potenciales de IA se guardan en la bandeja de entrada existente de /data y se vinculan con la conversación relacionada.',
    'fcc_ai.guide.title' => 'Cómo usar FCC AI',
    'fcc_ai.guide.subtitle' => 'Estas guías breves explican qué puede hacer cada IA y cómo aprovecharla al máximo en el trabajo diario.',
    'fcc_ai.guide.coach.title' => 'AI Coach',
    'fcc_ai.guide.coach.summary' => 'Apoyo para el trabajo de FCC, tu plan de crecimiento y los próximos pasos prácticos.',
    'fcc_ai.guide.coach.intro' => 'FCC Coach es tu asistente personal dentro de la plataforma. Está conectado a tu plan de crecimiento y te ayuda a tener claro cuál es el siguiente paso más útil.',
    'fcc_ai.guide.coach.point_1' => 'Puede ayudarte con la planificación, las prioridades, la concentración y el siguiente paso cuando te sientas estancado o no sepas bien qué hacer después.',
    'fcc_ai.guide.coach.point_2' => 'Ofrece ideas para contenido, comunicación, redes sociales y acciones diarias que apoyan el crecimiento del negocio.',
    'fcc_ai.guide.coach.point_3' => 'Te guía a través de Tu Plan de Crecimiento y te aconseja sobre lo que necesitas en este momento.',
    'fcc_ai.guide.coach.tip' => 'Obtendrás el máximo valor si escribes con claridad en qué punto estás, qué quieres lograr y qué tipo de ayuda necesitas ahora.',
    'fcc_ai.guide.sales.title' => 'IA para ventas, recomendaciones y colaboración empresarial',
    'fcc_ai.guide.sales.summary' => 'IA pública que recomienda productos, utiliza el blog y reconoce el interés en colaborar.',
    'fcc_ai.guide.sales.intro' => 'Esta IA conversa con los visitantes de tu aplicación FCC, les ayuda a encontrar productos para personas o mascotas y los orienta hacia el siguiente paso, una compra o una colaboración comercial.',
    'fcc_ai.guide.sales.point_1' => 'Responde preguntas, recomienda productos y puede dirigir al visitante al artículo adecuado del blog de FCC para una explicación más detallada.',
    'fcc_ai.guide.sales.point_2' => 'Acompaña al visitante durante todo el recorrido, desde la primera pregunta hasta una conversación posterior en el blog o el contacto.',
    'fcc_ai.guide.sales.point_3' => 'Puede recopilar datos de visitantes interesados y guardar un contacto potencial para que el socio pueda darle seguimiento.',
    'fcc_ai.guide.sales.point_4' => 'Puede reconocer el interés por el negocio y apoyar el patrocinio guiando a la persona visitante hacia el siguiente paso significativo.',
    'fcc_ai.guide.sales.tip' => 'Funciona mejor cuando el tono es claro, las reglas son sólidas y la lógica de recomendación está bien explicada.',
    'fcc_ai.guide.settings.title' => 'Configuración del asesor',
    'fcc_ai.guide.settings.summary' => 'Aquí defines cómo se expresa la IA pública, cómo responde y qué aspectos destaca.',
    'fcc_ai.guide.settings.intro' => 'En la configuración pública del asesor de IA, puedes ajustar la comunicación para que coincida con tu estilo, tu público y el objetivo de la aplicación.',
    'fcc_ai.guide.settings.point_1' => 'El nombre y el idioma del asistente determinan cómo se presenta la IA y qué idioma usa de forma natural.',
    'fcc_ai.guide.settings.point_2' => 'El tono ayuda a que la IA suene consultiva, comprensiva, amable o más directa, según lo que quieras.',
    'fcc_ai.guide.settings.point_3' => 'En las instrucciones de persona, describe el estilo que quieres: un trato más cálido, respuestas más breves, más preguntas, mayor enfoque en los productos o mayor enfoque en el negocio.',
    'fcc_ai.guide.settings.point_4' => 'En las reglas y límites, define qué debe mencionar siempre la IA, qué debe evitar y cómo debe formular sus recomendaciones.',
    'fcc_ai.guide.settings.tip' => 'Las instrucciones breves y concretas suelen funcionar mejor. Escríbelas como si explicaras cómo debería hablar con un visitante un asesor excelente.',
    'fcc_ai.guide.inbox.title' => 'Bandeja de entrada de IA de los últimos 30 días',
    'fcc_ai.guide.inbox.summary' => 'El lugar donde puedes hacer seguimiento de conversaciones y contactos potenciales, y mejorar la comunicación del chat con IA.',
    'fcc_ai.guide.inbox.intro' => 'La bandeja de entrada de IA muestra cómo interactuó realmente el asistente con usuarios reales. Es el mejor lugar para supervisar la calidad y seguir mejorando el asistente.',
    'fcc_ai.guide.inbox.point_1' => 'Abre las conversaciones y revisa dónde respondió bien la IA y dónde la respuesta podría ser más clara o útil.',
    'fcc_ai.guide.inbox.point_2' => 'Observa qué preguntas se repiten con frecuencia para que puedas mejorar el tono, las instrucciones de personalidad y las reglas.',
    'fcc_ai.guide.inbox.point_3' => 'Si los usuarios siguen pidiendo más explicaciones, acorta las respuestas, añade pasos más claros o guíalos mejor al blog o a la sección de contacto.',
    'fcc_ai.guide.inbox.point_4' => 'Haz un seguimiento de los clientes potenciales que genera la IA y usa esos datos para entender en qué medida el chat ayuda con las ventas y el patrocinio.',
    'fcc_ai.guide.inbox.tip' => 'Si notas el mismo problema más de una vez, ajusta de inmediato la configuración del asesor. Los pequeños cambios en el tono y las reglas suelen generar una gran mejora.',
